// Generated by vibelang from src/composerThreadItems.ts; the migrate flow writes it again with each batch.
import { foldSearchQuery, rankSearchItems, scoreThreadSearch } from "@t3tools/shared/paletteSearch";
import { threadSearchSubject, } from "#vibelang/emitted/src/state/threadSearch";
const COMPOSER_THREAD_RESULT_LIMIT = 5;
/**
 * Threads to reference from the composer, matched and ranked like the command
 * palette, without subagent threads. The agent can only read threads on its
 * own server, so candidates stay within the composer's environment.
 */
export function matchComposerThreadItems(input) {
    const query = foldSearchQuery(input.query);
    if (query.length === 0)
        return [];
    const candidates = input.shells.filter((shell) => shell.environmentId === input.environmentId &&
        shell.id !== input.excludeThreadId &&
        shell.archivedAt === null &&
        shell.lineage.relationshipToParent !== "subagent");
    return rankSearchItems(candidates, (shell, options) => scoreThreadSearch(query, threadSearchSubject(shell, null), input.now, {
        ...options,
        picks: false,
    }))
        .slice(0, COMPOSER_THREAD_RESULT_LIMIT)
        .map(({ item: shell }) => ({
        id: `thread:${shell.environmentId}:${shell.id}`,
        type: "thread",
        thread: { environmentId: shell.environmentId, threadId: shell.id },
        label: shell.title,
        description: "Thread",
    }));
}
/**
 * The user's machines the `@` picker offers, so the agent can link or work there. The
 * composer's own environment is left out. Like threads, they need a query: bare `@` stays a
 * file picker.
 */
export function matchComposerEnvironmentItems(input) {
    const query = input.query.trim().toLowerCase();
    if (query.length === 0)
        return [];
    return input.environments
        .filter((environment) => environment.environmentId !== input.environmentId &&
        environment.label.toLowerCase().includes(query))
        .map((environment) => ({
        id: `environment:${environment.environmentId}`,
        type: "environment",
        environmentId: environment.environmentId,
        machine: environment.machine,
        label: environment.label,
        description: "Machine",
    }));
}
